'use strict';
let effectsEnabled=localStorage.getItem('starlight-effects')!=='off',effectsContext;
function playEffect(kind='click'){if(!effectsEnabled)return;try{effectsContext??=new (window.AudioContext||window.webkitAudioContext)();effectsContext.resume();const notes=kind==='hit'?[180,90]:kind==='start'?[392,523,659]:kind==='finish'?[523,659,784,1047]:[740,988];notes.forEach((frequency,i)=>{const o=effectsContext.createOscillator(),g=effectsContext.createGain(),t=effectsContext.currentTime+i*.065;o.type='sine';o.frequency.setValueAtTime(frequency,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.065,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+.11);o.connect(g);g.connect(effectsContext.destination);o.start(t);o.stop(t+.12)})}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.effects!==undefined){effectsEnabled=!effectsEnabled;localStorage.setItem('starlight-effects',effectsEnabled?'on':'off');document.querySelectorAll('[data-effects]').forEach(v=>{v.textContent=effectsEnabled?'音效：開':'音效：關';v.setAttribute('aria-pressed',String(effectsEnabled))});if(effectsEnabled)playEffect();return}playEffect(b.dataset.quest?'start':'click')},true);
document.addEventListener('keydown',e=>{if(page==='landing'&&!e.repeat&&!['Tab','Shift','Control','Alt','Meta'].includes(e.key))playEffect('start')},true);
const adventureSoundButton=soundButton;soundButton=function(){return adventureSoundButton()+`<button class="nav-pill" data-effects aria-pressed="${effectsEnabled}">音效：${effectsEnabled?'開':'關'}</button>`};
const expeditionPlaces=[{name:'翠葉森林',sky:'#b9e4dc',far:'#80bba1',near:'#397a66',ground:'#7a9853',type:'forest'},{name:'琥珀山谷',sky:'#f4d8aa',far:'#c7a784',near:'#9b7963',ground:'#ad8959',type:'mountain'},{name:'月泉海岸',sky:'#abdce8',far:'#87b5cd',near:'#438eae',ground:'#d0bd82',type:'coast'},{name:'星光古城',sky:'#bac6e7',far:'#8f9fc2',near:'#677f9e',ground:'#8f9b85',type:'castle'}];
function adventureStage(){return `<div class="expedition" id="expedition" role="img" aria-label="勇者在橫向冒險世界行走"><div class="exp-sun"></div><div class="exp-clouds"></div><div class="exp-far"></div><div class="exp-near"></div><div class="exp-ground"></div><div class="exp-weather"></div><div class="exp-title"><span>FOCUS JOURNEY</span><strong id="exp-location">翠葉森林</strong><small id="exp-weather-name">晴朗</small></div><div class="exp-hero" style="background-position:${(data.hero%3)*50}% ${Math.floor(data.hero/3)*100}%"></div><div class="exp-monster"><div class="exp-enemy-art"></div><span id="exp-monster-name">森林史萊姆</span></div><div class="exp-strike" aria-hidden="true"></div><div class="exp-battle-note" id="exp-battle-note" aria-live="off"></div><div class="exp-distance" id="exp-distance">旅程開始</div></div><div class="exp-progress"><span id="exp-progress-bar"></span></div>`}
drawTimer=function(){const q=data.quests.find(q=>q.id===timer.id);openModal('timer',`<div class="timer-panel expedition-panel"><p class="subtle">${esc(q.detail)}</p>${adventureStage()}<div class="timer-number" id="timer-clock">${formatTime(timer.total-elapsed())}</div><p class="subtle" id="timer-note">準備好課本，勇者會陪住你一路前進。</p><div class="inline-actions" style="margin-top:20px"><button class="primary" data-action="pause" id="pause-btn">暫停休息</button><button class="ghost" data-action="save-timer">儲存並返回</button><button class="ghost" data-effects aria-pressed="${effectsEnabled}">音效：${effectsEnabled?'開':'關'}</button></div><div id="timer-finish"></div></div>`,'專注冒險 · '+q.title);$('.modal').classList.add('expedition-modal');timer.lastPlace=-1;timer.lastWeather=-1;timer.finishedSound=false;tickTimer()};
tickTimer=function(){if(!timer||!$('#timer-clock'))return;const e=elapsed(),stage=$('#expedition');$('#timer-clock').textContent=formatTime(timer.total-e);if(stage){stage.classList.toggle('is-paused',!timer.running);const place=Math.floor(e/45)%expeditionPlaces.length,weather=Math.floor(e/30)%4;if(place!==timer.lastPlace){const p=expeditionPlaces[place];stage.style.setProperty('--exp-sky',p.sky);stage.style.setProperty('--exp-ground',p.ground);stage.style.setProperty('--painted-scene',`url('assets/journey-${['forest','valley','coast','castle'][place]}.png')`);stage.querySelector('.exp-enemy-art').style.backgroundPosition=`${place%2*100}% ${Math.floor(place/2)*100}%`;$('#exp-location').textContent=p.name;stage.style.setProperty('--monster-color',['#8ec6aa','#dba66c','#87b9d4','#b6a0d2'][place]);$('#exp-monster-name').textContent=['森林史萊姆','琥珀小石怪','水滴精靈','星光小幽靈'][place];timer.lastPlace=place}if(weather!==timer.lastWeather){stage.dataset.weather=['sunny','rain','night','snow'][weather];$('#exp-weather-name').textContent=['晴朗 · 微風吹拂','細雨 · 滴答滴答','月夜 · 星光閃閃','飄雪 · 奇幻冬日'][weather];timer.lastWeather=weather}updateEncounter(stage,e,timer.running);$('#exp-distance').textContent=`旅程 ${Math.floor(e/60)} 分 ${Math.floor(e%60)} 秒 · ${Math.min(100,Math.floor(e/timer.total*100))}%`;$('#exp-progress-bar').style.width=Math.min(100,e/timer.total*100)+'%'}if(e>=timer.total){timer.acc=timer.total;timer.running=false;clearInterval(timer.handle);stage?.classList.add('is-paused');$('#pause-btn').disabled=true;$('#timer-note').textContent='旅程完成！記錄一下今次嘅努力。';if(!timer.finishedSound){playEffect('finish');timer.finishedSound=true}$('#timer-finish').innerHTML=`<p class="subtle" style="margin:20px 0 12px">今次完成咗幾多？</p><div class="inline-actions"><button class="primary small-btn" data-finish="complete">已完成任務</button><button class="ghost small-btn" data-finish="partial">做咗一部分</button><button class="ghost small-btn" data-finish="help">有啲地方唔明</button></div>`}};
function encounterState(seconds){const t=seconds%20;return {phase:t<7?'approach':t<10?'attack':t<13?'defeated':'travel',x:t<7?105-t/7*65:40,strike:Math.floor((t-7)*2)}}
function updateEncounter(stage,seconds,running){const state=encounterState(seconds);stage.dataset.encounter=state.phase;stage.style.setProperty('--enemy-x',state.x+'%');stage.style.setProperty('--attack-sway',state.strike%2?'1':'-1');const note=$('#exp-battle-note');if(note)note.textContent=state.phase==='attack'?'勇者出招！':state.phase==='defeated'?'擊退怪物，繼續前進！':'';if(state.phase==='attack'&&running&&timer.lastStrike!==Math.floor(seconds*2)){timer.lastStrike=Math.floor(seconds*2);playEffect('hit')}}
render();
